#!/usr/bin/env python3
"""Private global coherence proof variant. Guard every original before writes."""
from pathlib import Path
import hashlib,sys
PINS = {'Source/CloudInstructionPage.cpp': '940ceca6685467ce50ecc6f02c5640308281908eafdc7ed262676c4a1c17b393', 'Source/CloudInstructionPage.h': '9dd4af2ed8c74950341fe0eb2010676180a06dfb8324fd0bb9dd358b77521afe', 'Source/ee/EeExecutor.cpp': 'ea466c48a6ee09b8eaed50194ba689c2c958b495414c394468ffe9f58cafc3e1', 'Source/ee/EeExecutor.h': 'edb5bc887ae177a8583ee7eb46a59c97796a1d1c886a40fa469e94224ef67e47'}
CHANGES = [('Source/CloudInstructionPage.h', ' bool Equals(const void* source) const noexcept;\n', ' bool Equals(const void* source) const noexcept;\n // Registration saturates dense pages once; no popcount is needed at flush.\n static constexpr unsigned SPARSE_CHUNK_LIMIT = 16;\n static constexpr uint64_t FULL_COVERAGE = ~uint64_t(0);\n static uint64_t AddCoverage(uint64_t coverage, uint32_t page, uint32_t start, uint32_t end) noexcept;\n bool EqualsCovered(const void* source, uint64_t coverage) const noexcept;\n'), ('Source/CloudInstructionPage.cpp', 'bool CloudInstructionPage::Equals(const void* source) const noexcept\n', "uint64_t CloudInstructionPage::AddCoverage(uint64_t coverage, uint32_t page, uint32_t start, uint32_t end) noexcept\n{\n if(coverage == FULL_COVERAGE) return coverage;\n // Use wide exclusive endpoints, including the final instruction's four bytes.\n const uint64_t begin = page > start ? page : start;\n const uint64_t pageEnd = uint64_t(page) + SIZE;\n const uint64_t blockEnd = uint64_t(end) + 4;\n const uint64_t limit = pageEnd < blockEnd ? pageEnd : blockEnd;\n if(start > end || begin >= limit) return coverage;\n const unsigned first = unsigned((begin - page) / 64);\n const unsigned last = unsigned((limit - 1 - page) / 64);\n coverage |= (FULL_COVERAGE << first) & (FULL_COVERAGE >> (63 - last));\n unsigned count = 0;\n for(auto remaining = coverage; remaining; remaining &= remaining - 1)\n  if(++count > SPARSE_CHUNK_LIMIT) return FULL_COVERAGE;\n return coverage;\n}\n\nbool CloudInstructionPage::EqualsCovered(const void* source, uint64_t coverage) const noexcept\n{\n if(coverage == FULL_COVERAGE) return Equals(source);\n const auto* actual = static_cast<const uint8_t*>(source);\n#ifdef __wasm_simd128__\n const auto* saved = m_bytes.data();\n v128_t diff0 = wasm_i32x4_splat(0);\n v128_t diff1 = diff0, diff2 = diff0, diff3 = diff0;\n // All four lanes of every conservatively covered 64-byte chunk are checked.\n // The zero-mask guard also makes ctz well-defined; no load crosses the page.\n for(auto remaining = coverage; remaining; remaining &= remaining - 1)\n {\n  const unsigned offset = unsigned(__builtin_ctzll(remaining)) * 64;\n  diff0 = wasm_v128_or(diff0, wasm_v128_xor(wasm_v128_load(actual + offset), wasm_v128_load(saved + offset)));\n  diff1 = wasm_v128_or(diff1, wasm_v128_xor(wasm_v128_load(actual + offset + 16), wasm_v128_load(saved + offset + 16)));\n  diff2 = wasm_v128_or(diff2, wasm_v128_xor(wasm_v128_load(actual + offset + 32), wasm_v128_load(saved + offset + 32)));\n  diff3 = wasm_v128_or(diff3, wasm_v128_xor(wasm_v128_load(actual + offset + 48), wasm_v128_load(saved + offset + 48)));\n }\n return !wasm_v128_any_true(wasm_v128_or(wasm_v128_or(diff0, diff1), wasm_v128_or(diff2, diff3)));\n#else\n for(unsigned chunk = 0; chunk < SIZE / 64; ++chunk)\n  if((coverage & (uint64_t(1) << chunk)) && std::memcmp(m_bytes.data() + chunk * 64, actual + chunk * 64, 64) != 0) return false;\n return true;\n#endif\n}\n\nbool CloudInstructionPage::Equals(const void* source) const noexcept\n"), ('Source/ee/EeExecutor.h', '  std::set<uint32> entries;\n', '  std::set<uint32> entries;\n  // Conservative host-only coverage; dense masks saturate until page removal.\n  uint64_t coverage = 0;\n'), ('Source/ee/EeExecutor.cpp', '   found->second.entries.insert(start);\n', '   found->second.entries.insert(start);\n   found->second.coverage = CloudInstructionPage::AddCoverage(found->second.coverage, page, start, end);\n'), ('Source/ee/EeExecutor.cpp', '   if(page.snapshot->Equals(m_ram + pair.first)) continue;', '   if(page.snapshot->EqualsCovered(m_ram + pair.first, page.coverage)) continue;'), ('Source/ee/EeExecutor.h', '  std::set<uint32> entries;\n', '  std::set<uint32> entries;\n  // A newly compiled block must be validated even if bytes revert to the last\n  // page snapshot/hash before the next guest FlushCache.\n  bool pendingValidation = false;\n'), ('Source/ee/EeExecutor.cpp', '   found->second.entries.insert(start);\n', '   found->second.entries.insert(start);\n   found->second.pendingValidation = true;\n'), ('Source/ee/EeExecutor.cpp', '   if(page.hash == hash) continue;', '   if(!page.pendingValidation && page.hash == hash) continue;'), ('Source/ee/EeExecutor.cpp', '    changed.emplace_back(start, end + 4);\n  }\n }\n // Merge', '    changed.emplace_back(start, end + 4);\n  }\n  page.pendingValidation = false;\n }\n // Merge'), ('Source/ee/EeExecutor.cpp', '   if(page.snapshot->EqualsCovered(m_ram + pair.first, page.coverage)) continue;', '   if(!page.pendingValidation && page.snapshot->EqualsCovered(m_ram + pair.first, page.coverage)) continue;')]
def patch(root):
 root=Path(root)
 originals={n:(root/n).read_bytes() for n in PINS}
 for n,h in PINS.items():
  if hashlib.sha256(originals[n]).hexdigest()!=h:raise ValueError('Baseline source changed: '+n)
 outputs={n:b.decode() for n,b in originals.items()}
 for n,old,new in CHANGES:
  if outputs[n].count(old)!=1:raise ValueError('Source anchor changed: '+n)
  outputs[n]=outputs[n].replace(old,new,1)
 for n,s in outputs.items():
  if s.encode()!=originals[n]:(root/n).write_bytes(s.encode())
if __name__=='__main__':patch(sys.argv[1])
